A regression test in the pricing library asserts <code>a == b</code> on two PV totals. The totals sum the same three trade PVs, 0.1, 0.2 and 0.3, in a different order. Compile and run the snippet below; state what it prints and the fix.

<pre><code>#include &lt;cmath&gt;
#include &lt;iostream&gt;
#include &lt;vector&gt;

double total(const std::vector&lt;double&gt;&amp; pvs) {
    double s = 0.0;
    for (double x : pvs) s += x;
    return s;
}

int main() {
    std::vector&lt;double&gt; yesterday{0.1, 0.2, 0.3};
    std::vector&lt;double&gt; today{0.3, 0.2, 0.1};
    double a = total(yesterday);
    double b = total(today);
    std::cout &lt;&lt; std::boolalpha;
    std::cout.precision(17);
    std::cout &lt;&lt; "a = " &lt;&lt; a &lt;&lt; "\n";
    std::cout &lt;&lt; "b = " &lt;&lt; b &lt;&lt; "\n";
    std::cout &lt;&lt; "a == b : " &lt;&lt; (a == b) &lt;&lt; "\n";
    std::cout &lt;&lt; "|a-b| &lt; 1e-9 : " &lt;&lt; (std::abs(a - b) &lt; 1e-9) &lt;&lt; "\n";
    std::cout &lt;&lt; "0.1+0.2 == 0.3 : " &lt;&lt; (0.1 + 0.2 == 0.3) &lt;&lt; "\n";
}
</code></pre>
